function groupAnagrams(strs: string[]): string[][] {
  const groups = new Map<string, string[]>()
  for (const s of strs) {
    const key = [...s].sort().join('')
    const list = groups.get(key)
    if (list) list.push(s)
    else groups.set(key, [s])
  }
  return [...groups.values()]
}
